main();

async function ambilProfil(id: number) {
  return { id, nama: "Rina", poin: 120 };
}
type Profil = Awaited<ReturnType<typeof ambilProfil>>;
function level(p: Profil): string {
  return p.poin >= 100 ? "emas" : "perak";
}
async function main() {
  const p = await ambilProfil(1);
  console.log(p.nama, p.poin);
  console.log("Level:", level(p));
}
main();

