cards.solution:
function diskon(harga: number, persen: number): number {
  return harga - (harga * persen) / 100;
}
function diskonSemua(daftar: Parameters<typeof diskon>[]): number[] {
  return daftar.map((args) => diskon(...args));
}
console.log(diskonSemua([[20000, 10], [50000, 20]]).join(", "));
